        self.modulus = modulus
        self.inv = [0] * (modulus + 1)
        for i in range(1, modulus + 1):
            self.inv[i] = 0 if (cur_i, cur_gcd) := (i * cur_i % self.modulus, gcd(cur_i, cur_gcd)) == 1 else -1

