```python
MOD = 10**9 + 7

# Function to calculate combinations
def combinations(n, k):
    return math.comb(n, k)

# Function to count valid flags
def count_valid_flags(l, r):
    if r < 1 or r > 1e9:
        return 0

    # Base case: no flags
    if l > r - 1:
        return 0
    elif l == r - 1:
        return 2  # WB and BW

    # Initialize arrays for counts
    dp = [0] * 11
    w = [0] * 11
    b = [0] * 11
    r = [0] * 11
    w_to_bw_separated = [0] * 11

    # Count flags with 1 stripe
    w[1] = 1
    if combinations(r - 1, 1) % MOD != 0:
        b[1] = 1
    if combinations(r - 1, 1) < r:
        r[1] = combinations(r - 1, 1) % MOD
    w_to_bw_separated[1] = 1

    # Count flags with 2 stripes
    for i in range(2, r + 1):
        dp[i] = w[i - 1]
        b[i] = r[i - 2]
        r[i] = dp[i - 1]
        w_to_bw_separated[i] += w_to_bw_separated[i - 2]
        w_to_bw_separated[i - 1] += w_to_bw_separated[i]

    result = 0

    # Adjust counts based on the numbers of stripes
    for i in range(1, r):
        s = combinations(r - i, 2)
        if s == 0:
            continue
        if i == r // 2 and (r % 2 == 1 or i == 1):
            result += s * (r % 2)
        elif i > (r // 2):
            result += s
        elif i == 1 and (r % 2 == 1 or i == r // 2):
            result += s / 2
        else:
            result += s / 3

        # Adjust only for different midpoint cases now
        if i - 2 >= 0:
            result -= r[i - 2]
        if i - 1 >= 1:
            result -= w[i - 2]

        if i == 1:
            result -= 2

    return int(result % MOD)

# Example usage
