import math
import sys

def solve(X, m, n):
    points = [complex(0, 0)] * (n + 1)
    for i in range(1, n + 1):
        points[i] = complex(i - 1, 0)

    def get_coordinates(X, x, l):
        return (x - 1, 0) + l * mag_vec(points[x] - points[x - 1])

    for i in range(m):
        if sys.stdin.readline()[-1] == '1':
            x, l = map(int, input().split())
            if x > 100:
                continue
        else:
            x, a = map(int, input().split())
            a = -a * math.pi / 180

        for j in range(x, n + 1):
            v = points[j] - points[j - 1]
            points[j] += l * v * math.cos(a) + l * cmath.sqrt(1 - math.cos(a)**2) * v * math.sin(a)

    return '\n'.join(map(str, points))

if __name__ == "__main__":
    n, m = map(int, input().split())
    result = solve(n, m, n)
    print(result)
