import sys

def find_max_xor_path(tree, n):
    def dfs(node, parent, XOR):
        weight[node] = tree[node][2]  # Include the node's weight in the XOR
        max_xor = tree[node][2]  # Start with the node's weight XORed with itself

        for child in tree[node][1]:
            if child != parent:
                child_xor = -float('inf')  # Initialize child's XOR value
                for j in range(30):  # 30 bits for unsigned 33-bit integers
                    if (tree[node][2] >> j) & 1:  # Check if bit j is set in node's XOR
                        child_xor = max(child_xor, dfs(child, node, tree[child][2] >> j))  # Recurse to child
                    else:
                        carry = (tree[node][2] >> (j + 1)) & 1  # Carry bits if node's XOR has bit j set
                        child_xor = max(child_xor, dfs(child, node, tree[node][2] >> (j + 1)))
                        node_xor = tree[node][2] >> (j + 1)  # If no carrying, XOR from node to 0
                        if carry:
                            unused = (node_xor << (30 - (j + 1))) & 1  # Find unused bit in the child's weight
                            if unused:
                                child_xor = max(child_xor, node_xor << (30 - (j + 1)))

                max_xor = max(max_xor, child_xor + node_xor >> 1)  # Add child's XOR to node XOR, sharing results with neighbors

        return max_xor & ((1 << n) - 1)  # Right shift to remove extra bits not covered by XOR

    tree = {}
    for _ in range(n - 1):
        u, v, w = map(int, input().split())
        tree[u] = {'weight': w, 'children': {v}}
        tree[v] = {'weight': w, 'children': {u}}
        tree[u]['children'].append(v)
        tree[v]['children'].append(u)

    weight = [0] * (n + 1)
    for _ in range(n):
        u, v = map(int, input().split())
        weight[u] = 0
        weight[v] = 0

    return dfs(1, -1, 0)  # Start the recursion from the lowest-weight connected component

