import math

def subsetCount(n, k):
    return math.comb(n, k)

def solve(n, relationships):
    count = 0
    for mask in range(1, 2**n):
        good = 1
        for i in range(1, n):
            if mask & (1 << i):
                for j in range(i + 1, n):
                    if mask & (1 << j):
                        if relationships[i][j] != relationships[j][i]:
                            good = 0
                            break
                if not good:
                    break
        if good:
            m = subsetCount(n - 1, n - 1)
            for i in range(1, n):
                for j in range(i + 1, n):
                    if mask & (1 << i) and mask & (1 << j):
                        m -= subsetCount(n - 2, i - 1) * subsetCount(n - 2, j - 1 - i) * 2
            count += m
    return count

