import sys

def find_edges(n, edges):
    tree = [0] * n
    for a, b, c in edges:
        tree[a-1] += c
        tree[b-1] += c
    return map(sum, tree)

def edge_cost(n, edges, surface):
    cost = sum(map(lambda x: x - min(x, surface), find_edges(n, edges)))
    return cost

def main():
    n, m = map(int, input().split())
    edges = [[0, 0, 0]] + [[*map(int, input().split())] for _ in range(m - 1)]
    surface = [int(input()) for _ in range(2)]
    queries = [[int(input()) for _ in range(2)] for _ in range(int(input()))]
    for a, b in queries:
        print(-1 if edge_cost(n, edges, surface) == min(edge_cost(n, edges, surface), -1 * min(a - surface[a - 1], b - surface[b - 1])) else edge_cost(n, edges, surface))

if __name__ == "__main__":
    main()
