        return pow(-1, mod_minus(start, end)) * pow(3 + end, mod_minus(start, end)) + pow(-3, mod_minus(start, end))
    return (pow(-3, mod_minus(start, end)) + pow(-2, mod_minus(start, end)) * pow(-3, mod_minus(end - start - 1, end)) * (3 + end)) % MOD

def mod_minus(i, j):
    return (i - j + MOD) % MOD

